import { useId, useRef, type KeyboardEvent } from "react";
import "./SegmentedControl.css";

export interface SegmentedOption<T extends string> {
  value: T;
  label: string;
}

export interface SegmentedControlProps<T extends string> {
  label: string;
  options: readonly SegmentedOption<T>[];
  value: T;
  onChange: (value: T) => void;
}

export function SegmentedControl<T extends string>({
  label,
  options,
  value,
  onChange,
}: SegmentedControlProps<T>) {
  const labelId = useId();
  const buttonRefs = useRef<(HTMLButtonElement | null)[]>([]);

  if (options.length === 0) {
    return null;
  }

  const selectedIndex = options.findIndex((option) => option.value === value);
  // Roving tabindex: only one radio is in the Tab order. If nothing matches
  // the current value, the first option takes that role.
  const tabStopIndex = selectedIndex === -1 ? 0 : selectedIndex;

  const choose = (index: number) => {
    const option = options[index];
    if (option === undefined) {
      return;
    }
    onChange(option.value);
    buttonRefs.current[index]?.focus();
  };

  const handleKeyDown = (event: KeyboardEvent<HTMLButtonElement>, index: number) => {
    const last = options.length - 1;
    let next: number;

    switch (event.key) {
      case "ArrowRight":
      case "ArrowDown":
        next = index === last ? 0 : index + 1;
        break;
      case "ArrowLeft":
      case "ArrowUp":
        next = index === 0 ? last : index - 1;
        break;
      case "Home":
        next = 0;
        break;
      case "End":
        next = last;
        break;
      default:
        return;
    }

    event.preventDefault();
    choose(next);
  };

  return (
    <div className="segmented">
      <span className="segmented__label" id={labelId}>
        {label}
      </span>
      <div className="segmented__track" role="radiogroup" aria-labelledby={labelId}>
        {options.map((option, index) => {
          const checked = index === selectedIndex;
          return (
            <button
              key={option.value}
              ref={(element) => {
                buttonRefs.current[index] = element;
              }}
              type="button"
              role="radio"
              aria-checked={checked}
              tabIndex={index === tabStopIndex ? 0 : -1}
              className="segmented__option"
              onClick={() => onChange(option.value)}
              onKeyDown={(event) => handleKeyDown(event, index)}
            >
              {option.label}
            </button>
          );
        })}
      </div>
    </div>
  );
}
