.segmented {
  display: inline-flex;
  flex-direction: column;
  gap: 0.4rem;
  color: var(--ink);
}

.segmented__label {
  font-size: clamp(0.8rem, 0.5rem + 0.6vw, 0.95rem);
  color: var(--muted);
}

.segmented__track {
  display: inline-flex;
  align-items: stretch;
  padding: 0.25rem;
  gap: 0.25rem;
  border: 1px solid var(--muted);
  border-radius: 999px;
  background: var(--code-bg);
}

.segmented__option {
  font: inherit;
  font-size: clamp(0.85rem, 0.6rem + 0.7vw, 1rem);
  line-height: 1.2;
  padding: 0.4rem 0.9rem;
  border: 1px solid transparent;
  border-radius: 999px;
  background: transparent;
  color: var(--muted);
  cursor: pointer;
  transition: background-color 150ms ease, color 150ms ease;
}

.segmented__option:hover {
  background: var(--myelin-wash);
  color: var(--ink);
}

.segmented__option[aria-checked="true"] {
  background: var(--myelin);
  color: var(--slide);
}

.segmented__option[aria-checked="true"]:hover {
  background: var(--myelin);
  color: var(--slide);
}

:root[data-motion="reduce"] .segmented__option {
  transition: none;
}

@media (prefers-reduced-motion: reduce) {
  .segmented__option {
    transition: none;
  }
}
